struct se_portal_group *create_tpg(struct se_wwn *wwn, struct config_group *group, const char *name) {
    struct se_portal_group *tpg;
    char *endptr;
    unsigned long tpgt;

    if (strncmp(name, "tpgt_", strlen("tpgt_")) != 0) {
        pr_err("Invalid TPG name %s, must start with \"tpgt_\"\n", name);
        return ERR_PTR(-EINVAL);
    }

    tpgt = simple_strtoul(name + strlen("tpgt_"), &endptr, 10);
    if (*endptr != '\0') {
        pr_err("Invalid TPG numeric ID in %s\n", name);
        return ERR_PTR(-EINVAL);
    }

    tpg = kzalloc(sizeof(*tpg), GFP_KERNEL);
    if (!tpg)
        return ERR_PTR(-ENOMEM);

    tpg->tpg_wwn = wwn;
    tpg->tpg_group = group;
    tpg->tpgt = tpgt;
    spin_lock_init(&tpg->tpg_lock);

    if (core_scsi3_tpg_register(tpg)) {
        kfree(tpg);
        return ERR_PTR(-EINVAL);
    }

    mutex_lock(&tpg_mutex);
    list_add_tail(&tpg->tpg_list, &tpg_list);
    mutex_unlock(&tpg_mutex);

    return tpg;
}

