struct se_portal_group *create_target_portal_group(struct se_wwn *wwn,
                                                  struct config_group *group,
                                                  const char *name)
{
    struct se_portal_group *tpg;
    int ret;

    if (!name || strncmp(name, "tpgt_", 5) != 0)
        return ERR_PTR(-EINVAL);

    tpg = kzalloc(sizeof(*tpg), GFP_KERNEL);
    if (!tpg)
        return ERR_PTR(-ENOMEM);

    tpg->wwn = wwn;
    tpg->group = group;
    tpg->name = kstrdup(name, GFP_KERNEL);
    if (!tpg->name) {
        kfree(tpg);
        return ERR_PTR(-ENOMEM);
    }

    mutex_lock(&target_global_lock);
    ret = register_tpg(tpg);
    if (ret < 0) {
        mutex_unlock(&target_global_lock);
        kfree(tpg->name);
        kfree(tpg);
        return ERR_PTR(ret);
    }

    list_add(&tpg->tpg_list, &target_tpg_list);
    mutex_unlock(&target_global_lock);

    return tpg;
}
